/**
 * Smart image framing — subject-aware crop for every .go-frame thumbnail.
 *
 * Ported from news-magazine-x/assets/js/go-smart-image-framing.js (kept the
 * exact perf safeguards that were hard-won there: off-main-thread decode via
 * createImageBitmap, IntersectionObserver gating, 8ms idle-slice budget — an
 * earlier version without the slice budget froze the main thread for ~17s).
 * Only the selectors changed, to match this theme's single `.go-frame`
 * wrapper instead of news-magazine-x's per-context class list.
 */
(function () {
	'use strict';

	var processed = new WeakSet();
	var queued = new WeakSet();
	var observed = new WeakSet();
	var queue = [];
	var running = false;
	var SLICE_BUDGET_MS = 8;
	var isHome = document.body && document.body.classList.contains('home');
	var isDesktopHome = isHome && window.matchMedia && window.matchMedia('(min-width: 901px)').matches;

	/*
	 * Homepage desktop is intentionally excluded. A dense desktop home exposes
	 * many card images at once; changing object-position after first paint makes
	 * the whole viewport appear to flash even when element geometry does not
	 * move. Server/CSS crops are deterministic there. Mobile keeps the smart
	 * framing enhancement, where fewer cards are visible simultaneously.
	 */
	if (isDesktopHome) {
		return;
	}

	var selector = '.go-frame img, .go-tile__media img, .go-stream__media img, .go-article-sidebar__thumb img, .go-inline-related__media img, .go-archive-hero__media img, .go-archive-hero__item-media img, .go-archive-row__media img, .go-scored-masthead__media img, .go-after-related-feature__media img, .go-after-related-row__media img, .go-after-review-feature__media img, .go-after-review-mini__media img, .entry-content figure.wp-block-image img, .entry-content figure.wp-caption img, .entry-content p > img, .entry-content p > a > img';
	var frameSelector = '.go-frame, .go-tile__media, .go-stream__media, .go-article-sidebar__thumb, .go-inline-related__media, .go-archive-hero__media, .go-archive-hero__item-media, .go-archive-row__media, .go-scored-masthead__media, .go-after-related-feature__media, .go-after-related-row__media, .go-after-review-feature__media, .go-after-review-mini__media, figure.wp-block-image, figure.wp-caption';

	function isExcluded(img) {
		var src = (img.currentSrc || img.src || '').toLowerCase();
		var className = String(img.className || '').toLowerCase();
		var alt = String(img.alt || '').toLowerCase();

		return img.getAttribute('data-go-smart-crop') === 'off' ||
			img.hasAttribute('data-go-image-geometry') ||
			Boolean(img.style && img.style.objectPosition) ||
			!src ||
			src.indexOf('.svg') !== -1 ||
			img.closest('.go-header, .go-offcanvas, .go-logo, .wp-admin') ||
			className.indexOf('logo') !== -1 ||
			className.indexOf('avatar') !== -1 ||
			className.indexOf('emoji') !== -1 ||
			alt.indexOf('logo') !== -1;
	}

	function getFrame(img) {
		var frame = img.closest(frameSelector);
		if (frame) {
			return frame;
		}

		/* Classic/legacy WordPress content often stores editorial images as
		 * <p><img> or <p><a><img>. CSS gives the image the 16:9 geometry, so
		 * the image itself is the safest framing box; using the paragraph would
		 * include caption/text height and distort the crop calculation. */
		if (img.matches('.entry-content p > img, .entry-content p > a > img')) {
			return img;
		}

		return null;
	}

	function clamp(value, min, max) {
		return Math.max(min, Math.min(max, value));
	}

	function getPixelScore(data, index, width, x, y) {
		var r = data[index];
		var g = data[index + 1];
		var b = data[index + 2];
		var a = data[index + 3] / 255;

		if (a < 0.45) {
			return 0;
		}

		var lum = (0.2126 * r) + (0.7152 * g) + (0.0722 * b);
		var max = Math.max(r, g, b);
		var min = Math.min(r, g, b);
		var sat = max === 0 ? 0 : (max - min) / max;
		var contrast = 0;
		var edge = 0;

		if (x > 0) {
			var left = index - 4;
			var leftLum = (0.2126 * data[left]) + (0.7152 * data[left + 1]) + (0.0722 * data[left + 2]);
			contrast += Math.abs(lum - leftLum);
		}

		if (y > 0) {
			var up = index - (width * 4);
			var upLum = (0.2126 * data[up]) + (0.7152 * data[up + 1]) + (0.0722 * data[up + 2]);
			edge += Math.abs(lum - upLum);
		}

		var skin = 0;
		if (r > 78 && g > 42 && b > 26 && r > g && g > b && (r - b) > 24 && (r - g) > 8) {
			skin = 48;
		}

		var vivid = sat * 44;
		var detail = (contrast * 0.55) + (edge * 0.55);
		var brightness = lum > 28 && lum < 232 ? 14 : -12;

		return Math.max(0, detail + vivid + skin + brightness);
	}

	function getSampleSize(img) {
		var naturalWidth = img.naturalWidth || 0;
		var naturalHeight = img.naturalHeight || 0;

		if (naturalWidth < 96 || naturalHeight < 72) {
			return null;
		}

		var sampleWidth = isHome ? 72 : 96;
		var sampleHeight = Math.max(56, Math.round((naturalHeight / naturalWidth) * sampleWidth));

		if (sampleHeight > (isHome ? 104 : 128)) {
			sampleHeight = isHome ? 104 : 128;
			sampleWidth = Math.max(56, Math.round((naturalWidth / naturalHeight) * sampleHeight));
		}

		return { width: sampleWidth, height: sampleHeight };
	}

	function scoreSource(source, sampleWidth, sampleHeight) {
		var canvas = document.createElement('canvas');
		canvas.width = sampleWidth;
		canvas.height = sampleHeight;

		var ctx = canvas.getContext('2d', { willReadFrequently: true });
		if (!ctx) {
			return null;
		}

		try {
			ctx.drawImage(source, 0, 0, sampleWidth, sampleHeight);
			var pixels = ctx.getImageData(0, 0, sampleWidth, sampleHeight).data;
		} catch (error) {
			return null;
		}

		var total = 0;
		var xTotal = 0;
		var yTotal = 0;

		for (var y = 0; y < sampleHeight; y += 2) {
			for (var x = 0; x < sampleWidth; x += 2) {
				var index = ((y * sampleWidth) + x) * 4;
				var xNorm = x / sampleWidth;
				var yNorm = y / sampleHeight;
				var centerBias = 1 - (Math.abs(xNorm - 0.5) * 0.62);
				var upperBias = 1 - (Math.max(0, yNorm - 0.78) * 0.18);
				var score = getPixelScore(pixels, index, sampleWidth, x, y) * centerBias * upperBias;

				if (score <= 0) {
					continue;
				}

				total += score;
				xTotal += xNorm * score;
				yTotal += yNorm * score;
			}
		}

		if (!total) {
			return null;
		}

		return {
			x: clamp((xTotal / total) * 100, 28, 72),
			y: clamp((yTotal / total) * 100, 24, 68)
		};
	}

	function analyze(img) {
		var sample = getSampleSize(img);

		if (!sample) {
			return Promise.resolve(null);
		}

		// createImageBitmap decodes + downscales off the main thread, avoiding
		// a synchronous full-size decode via drawImage(img) directly.
		if (typeof window.createImageBitmap === 'function') {
			return window.createImageBitmap(img, {
				resizeWidth: sample.width,
				resizeHeight: sample.height
			}).then(function (bitmap) {
				var focus = scoreSource(bitmap, sample.width, sample.height);

				if (bitmap.close) {
					bitmap.close();
				}

				return focus;
			}).catch(function () {
				return scoreSource(img, sample.width, sample.height);
			});
		}

		return Promise.resolve(scoreSource(img, sample.width, sample.height));
	}

	function applyFrame(img) {
		if (processed.has(img) || isExcluded(img)) {
			return Promise.resolve();
		}

		var frame = getFrame(img);
		if (!frame) {
			return Promise.resolve();
		}

		var rect = frame.getBoundingClientRect();
		if (rect.width < 72 || rect.height < 48) {
			return Promise.resolve();
		}

		return analyze(img).then(function (focus) {
			if (!focus) {
				focus = { x: 50, y: 40 };
			}

			var imageRatio = (img.naturalWidth || rect.width) / Math.max(1, img.naturalHeight || rect.height);
			var frameRatio = rect.width / Math.max(1, rect.height);

			if (imageRatio > frameRatio * 1.1) {
				focus.y = clamp(focus.y, 30, 64);
			} else if (imageRatio < frameRatio * 0.74) {
				focus.y = clamp(focus.y, 24, 72);
			}

			var xValue = focus.x.toFixed(2) + '%';
			var yValue = focus.y.toFixed(2) + '%';

			img.style.objectPosition = xValue + ' ' + yValue;
			frame.classList.add('go-smart-framed');
			img.classList.add('go-smart-framed-img');
			processed.add(img);
		});
	}

	function schedulePump() {
		if (running) {
			return;
		}

		running = true;
		if ('requestIdleCallback' in window) {
			window.requestIdleCallback(pump, { timeout: 240 });
		} else {
			window.requestAnimationFrame(pump);
		}
	}

	function pump() {
		// Always slice the work: even when the idle callback fires on
		// timeout, running the whole queue at once freezes the main thread.
		processNext(Date.now());
	}

	function processNext(sliceStart) {
		if (!queue.length) {
			running = false;
			return;
		}

		if (Date.now() - sliceStart > SLICE_BUDGET_MS) {
			running = false;
			schedulePump();
			return;
		}

		var img = queue.shift();
		queued.delete(img);

		applyFrame(img).then(function () {
			processNext(sliceStart);
		}, function () {
			processNext(sliceStart);
		});
	}

	function enqueue(img) {
		if (!img || processed.has(img) || queued.has(img) || isExcluded(img)) {
			return;
		}

		if (!img.complete || !img.naturalWidth) {
			img.addEventListener('load', function onLoad() {
				img.removeEventListener('load', onLoad);
				enqueue(img);
			}, { once: true });
			return;
		}

		queued.add(img);
		queue.push(img);
		schedulePump();
	}

	var intersectionObserver = 'IntersectionObserver' in window ? new IntersectionObserver(function (entries) {
		entries.forEach(function (entry) {
			if (entry.isIntersecting) {
				intersectionObserver.unobserve(entry.target);
				enqueue(entry.target);
			}
		});
	}, { rootMargin: '900px 0px' }) : null;

	function observeImage(img) {
		if (!img || processed.has(img) || queued.has(img)) {
			return;
		}

		if (intersectionObserver) {
			if (!observed.has(img)) {
				observed.add(img);
				intersectionObserver.observe(img);
			}
			return;
		}

		enqueue(img);
	}

	function scan(root) {
		var scope = root && root.querySelectorAll ? root : document;
		scope.querySelectorAll(selector).forEach(observeImage);
	}

	/* Third-party advertising can mutate its own subtree repeatedly after fill.
	 * Smart framing only targets first-party editorial thumbnails, so traversing
	 * those mutations burns main-thread time without ever producing a candidate. */
	var mutationIgnoreSelector = '.go-ad-slot, .go-adsense-placement, .google-auto-placed, ins.adsbygoogle, .go-smart-ad, .go-anchor';

	function isIgnoredMutationScope(node) {
		if (!node) {
			return false;
		}
		var element = node.nodeType === 1 ? node : node.parentElement;
		return Boolean(element && element.closest && element.closest(mutationIgnoreSelector));
	}

	function isIgnoredMutationNode(node) {
		if (!node || node.nodeType !== 1) {
			return true;
		}
		if (node.matches && node.matches('script, style, link, noscript, iframe')) {
			return true;
		}
		return isIgnoredMutationScope(node);
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', function () {
			scan(document);
		});
	} else {
		scan(document);
	}

	window.addEventListener('load', function () {
		scan(document);
	}, { once: true });

	if ('MutationObserver' in window) {
		new MutationObserver(function (mutations) {
			mutations.forEach(function (mutation) {
				if (isIgnoredMutationScope(mutation.target)) {
					return;
				}
				mutation.addedNodes.forEach(function (node) {
					if (isIgnoredMutationNode(node)) {
						return;
					}

					if (node.matches && node.matches(selector)) {
						observeImage(node);
					} else {
						scan(node);
					}
				});
			});
		}).observe(document.documentElement, { childList: true, subtree: true });
	}
}());
